import { Menubar } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function MenubarExample() {
  const [value, setValue] = useState('No command run.');
  return (
    <div style={stack}>
      <Menubar
        items={[
          {
            id: 'file',
            label: 'File',
            entries: [
              { id: 'new', label: 'New document' },
              { id: 'save', label: 'Save document' },
            ],
          },
          {
            id: 'edit',
            label: 'Edit',
            entries: [
              { id: 'undo', label: 'Undo change' },
              { id: 'redo', label: 'Redo change' },
            ],
          },
        ]}
        onSelect={(id) =>
          setValue(
            (
              {
                new: 'Document created.',
                save: 'Document saved.',
                undo: 'Change undone.',
                redo: 'Change redone.',
              } as Record<string, string>
            )[id],
          )
        }
      />
      <p role="status">{value}</p>
    </div>
  );
}
export function Example() {
  return <MenubarExample />;
}
